Map<String, bool> posProfileFeatures(String profile, {Map<String, bool> current = const {}}) => {
  ...posProfilePresets['retail']!,
  ...(profile == 'custom' ? current : posProfilePresets[profile] ?? posProfilePresets['retail']!),
};

List<String> posFulfillmentOptions(String profile, Map<String, bool> features) => [
  if (features['use_tables'] == true) 'dine_in',
  if (profile == 'restoran') 'free_table',
  'take_away',
  if (features['use_delivery'] == true) 'delivery',
  if (features['use_appointments'] == true) 'reservation',
  if (profile == 'restoran') 'quick_service',
];
